window.__finlexDocLoaded(10192,{"id":10192,"articles":[{"id":1000799,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Governs equity-classified and liability-classified share-based payment awards to both employees and nonemployees (aligned by ASU 2018-07), measured at grant-date fair value.","seq":0},{"id":1000800,"no":"ASC 718-10 / 718-20","heading":"Grant-Date Fair Value, Graded Vesting & Forfeiture Policy","text":"• Service/Performance/Market Conditions (ASC 718-10-30): Service & performance conditions affect quantity of awards vested; market conditions (e.g., TSR) are baked into grant-date fair value.\n• Graded Vesting Policy Election (ASC 718-10-35-8): For awards with ONLY service conditions, entities may elect STRAIGHT-LINE attribution over the total requisite service period (or accelerated tranche-by-tranche attribution).\n• Forfeitures (ASU 2016-09): Policy election to either estimate forfeitures upfront OR account for forfeitures as they occur; excess tax benefits/deficiencies are recognized in Income Tax Expense (P&L), not APIC.","seq":1},{"id":1000801,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Three Key Divergences from IFRS 2 / CAS 11: (1) Graded vesting — US GAAP permits straight-line attribution, whereas IFRS 2 MANDATES accelerated tranche-by-tranche attribution; (2) Forfeitures — US GAAP allows recognizing as incurred; (3) Deferred taxes — US GAAP books excess tax benefits to P&L (IFRS 2 caps P&L tax benefit at book expense and puts excess in equity).","seq":2},{"id":1000802,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
